style.css:
@-moz-document url("http://produktion.sog.sanner/bestellungen/index.html"), url("http://produktion.sog.sanner/bestellungen/post.php"), url("http://produktion.sog.sanner/bestellungen/index.php"), url-prefix("http://produktion.sog.sanner/bestellungen/") {
/* Tło i typografia */
  html, body {
    background: #0e1116 !important; /* grafitowe tło */
    color: #e6f4ea !important;
    font-family: "Segoe UI", Roboto, Arial, sans-serif !important;
    font-size: 14px !important;
    margin: 16px !important;
  }

  /* frameset dla index.html */
  frameset, frame {
    background: #0e1116 !important;
    border: 0 !important;
  }
  body::before, frameset::before {
    content: "";
    display: block;
    height: 3px;
    background: linear-gradient(90deg, #2e7d32, #66bb6a) !important;
  }

  /* Tabele główne */
  table {
    width: 100% !important;
    border-collapse: collapse !important;
    margin: 16px 0 !important;
    border: 1px solid #1b212b !important;
    border-radius: 10px !important;
    overflow: hidden !important;
    box-shadow: 0 6px 18px rgba(0,0,0,.35) !important;
    background: #151a21 !important; /* ciemne wnętrze */
  }

  td {
    padding: 10px 12px !important;
    border-bottom: 1px solid #222a35 !important;
  }

  /* Nagłówek tabeli */
  table > tbody > tr:first-child td,
  table > tr:first-child td {
    background: linear-gradient(90deg, #1b5e20, #43a047) !important;
    color: #eafff1 !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
    letter-spacing: .04em !important;
  }

  /* Kontrast dla statusów */
  tr[bgcolor] td { color: #102215 !important; }
  tr[bgcolor="#DF01D7"] td { color: #4a0032 !important; }
  tr[bgcolor="#A9D0F5"] td { color: #0b2f58 !important; }
  tr[bgcolor="#BCF5A9"] td { color: #0f3a1a !important; }

  /* Przyciski akcji */
  td a[href*="view.php"] {
    display: inline-block !important;
    padding: 4px 10px !important;
    background: #2e7d32 !important;
    color: #eafff1 !important;
    text-decoration: none !important;
    border-radius: 8px !important;
    border: 1px solid #1b5e20 !important;
    transition: transform .08s ease, filter .2s ease !important;
    box-shadow: 0 2px 8px rgba(0,0,0,.3) !important;
  }
  td a[href*="view.php"]:hover {
    transform: translateY(-1px) !important;
    filter: brightness(1.08) !important;
  }

  /* Hover wiersza */
  tr:hover td {
    background: #10151b !important;
  }

  /* Linie i legenda */
  hr {
    border: 0 !important;
    height: 2px !important;
    background: linear-gradient(90deg, #2e7d32, #81c784) !important;
  }

  table:last-of-type td {
    font-size: 12px !important;
    opacity: .95 !important;
  }
}
